        public R24KnifePhysics(Transform world,Func<Collider,bool> actorOrIgnored,Func<Collider,string> actualTargetId,Func<Vector3,Vector3,string,bool> actualLineClear){if(world==null||actualTargetId==null||actualLineClear==null)throw new ArgumentNullException("actual knife scene ports");ignored=actorOrIgnored;targetId=actualTargetId;lineClear=actualLineClear;var go=new GameObject("Source knife continuous swept-volume query");go.layer=ProbeLayer;go.hideFlags=HideFlags.HideInHierarchy|HideFlags.DontSave;root=go.transform;root.SetParent(world,false);probe=go.AddComponent<MeshCollider>();probe.enabled=false;probe.convex=true;probe.cookingOptions=MeshColliderCookingOptions.EnableMeshCleaning|MeshColliderCookingOptions.WeldColocatedVertices|MeshColliderCookingOptions.CookForFasterSimulation;mesh=new Mesh();mesh.name="Actual source thick swept blade convex cloud";}
        static Vector3 V(Float3 a){return new Vector3(a.X,a.Y,a.Z);}static Float3 F(Vector3 a){return new Float3(a.x,a.y,a.z);}
        List<Contact> Query(Float3 oldBase,Float3 oldTip,Float3 lower,Float3 tip,float margin){HullQueries++;var points=R24KnifeMath.HullPoints(oldBase,oldTip,lower,tip,margin+.001f);Vector3 center=(V(oldBase)+V(oldTip)+V(lower)+V(tip))*.25f;var vertices=new Vector3[points.Length];var bounds=new Bounds(V(points[0]),Vector3.zero);for(int i=0;i<vertices.Length;i++){var point=V(points[i]);vertices[i]=point-center;bounds.Encapsulate(point);}var triangles=new int[(vertices.Length-2)*3];for(int i=0;i<vertices.Length-2;i++){triangles[i*3]=0;triangles[i*3+1]=i+1;triangles[i*3+2]=i+2;}
