            var found=new Dictionary<string,Contact>(StringComparer.Ordinal);foreach(var candidate in candidates){
                var collider=candidate.Key;string id=candidate.Value;Vector3 direction;float distance;if(!Physics.ComputePenetration(probe,center,Quaternion.identity,collider,collider.transform.position,collider.transform.rotation,out direction,out distance))continue;
                // Recover a real surface point on the intersected collider, not a
                // target origin or a second weapon/gaze ray. Penetration normal
                // selects the outside side of the actual convex contact.
                float supportDot=float.PositiveInfinity;Vector3 bladePoint=Vector3.zero;int supportCount=0;foreach(var sourcePoint in points){var sample=V(sourcePoint);float dot=Vector3.Dot(sample,direction);if(dot<supportDot-.000001f){supportDot=dot;bladePoint=sample;supportCount=1;}else if(Mathf.Abs(dot-supportDot)<=.000001f){bladePoint+=sample;supportCount++;}}bladePoint/=Mathf.Max(1,supportCount);var outside=bladePoint+direction*(distance+.002f);Vector3 point;if(!SurfacePoint(collider,outside,out point))continue;var contact=new Contact{Id=id,Collider=collider,Point=point,Normal=direction,Distance=(point-V(oldBase)).sqrMagnitude};Contact prior;if(!found.TryGetValue(id,out prior)||contact.Distance<prior.Distance)found[id]=contact;
            }
