        public int Sample(R24KnifeRuntime owner,float dt,bool usable,R23ShotPose actor,R23ShotPose blade,Float3 gripWorld,Float3 head,Func<R24KnifeHit,bool> applyActualContact){LastSubsteps=LastAcceptedEntries=LastActualDamage=0;if(disposed||owner==null)return 0;if(!usable||!blade.Valid||!actor.Valid||!gripWorld.IsFinite||!head.IsFinite){owner.BeginFrame(dt,false,actor,new Float3(),new Float3(),new Float3(),new string[0]);return 0;}var lower=blade.Point(R24KnifeRuntime.BladeBase);var tip=blade.Point(R24KnifeRuntime.BladeTip);var initial=Query(lower,tip,lower,tip,0);var sweep=owner.BeginFrame(dt,true,actor,lower,tip,gripWorld,Ids(initial));if(sweep==null)return 0;LastSubsteps=sweep.Steps;
            for(int i=0;i<sweep.Steps;i++){Float3 oldBase,oldTip,nextBase,nextTip;sweep.ReadStep(i,out oldBase,out oldTip,out nextBase,out nextTip);var raw=Query(oldBase,oldTip,nextBase,nextTip,0);var touching=Query(nextBase,nextTip,nextBase,nextTip,0);var retained=Query(nextBase,nextTip,nextBase,nextTip,R24KnifeRuntime.ExitHysteresis);var visible=new List<Contact>();foreach(var contact in raw)if(lineClear(V(head),V(nextBase),contact.Id)&&lineClear(V(nextBase),contact.Point,contact.Id))visible.Add(contact);var entries=owner.SampleStep(sweep,i,Ids(visible),Ids(touching),Ids(retained));LastAcceptedEntries+=entries.Length;var direction=(V(nextTip)-V(oldTip)).normalized;if(direction.sqrMagnitude<.000001f)direction=(V(nextBase)-V(oldBase)).normalized;
                // Freeze this substep's spatial contacts before callbacks can destroy
                // a panel. The next substep queries the resulting actual scene.
                var decisions=new List<R24KnifeHit>();foreach(var entry in entries)foreach(var contact in visible)if(entry.TargetId==contact.Id){decisions.Add(new R24KnifeHit(entry,contact.Collider,contact.Point,contact.Normal,direction));break;}foreach(var decision in decisions)if(applyActualContact!=null&&applyActualContact(decision))LastActualDamage++;
            }
