        }
        public void Dispose(){if(disposed)return;disposed=true;if(probe!=null)probe.sharedMesh=null;if(mesh!=null)UnityEngine.Object.Destroy(mesh);if(root!=null)UnityEngine.Object.Destroy(root.gameObject);}
    }
